package com.bank.sched;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Computes minimum intervals to run all jobs with a cooldown between repeats.
public class BatchScheduler {

    private static final Logger log = Logger.getLogger(BatchScheduler.class.getName());

    public int leastIntervals(char[] jobs, int cooldown) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char j : jobs) {
            freq.merge(j, 1, Integer::sum);
        }
        int maxCount = 0;
        for (int c : freq.values()) {
            maxCount = Math.max(maxCount, c);
        }
        int tiedAtMax = 0;
        for (int c : freq.values()) {
            if (c == maxCount) tiedAtMax++;
        }
        // skeleton forced by the busiest job type
        int skeleton = (maxCount - 1) * (cooldown + 1) + tiedAtMax;
        int result = Math.max(skeleton, jobs.length);
        log.info("Jobs=" + jobs.length + " cooldown=" + cooldown
                + " maxCount=" + maxCount + " tiedAtMax=" + tiedAtMax
                + " -> intervals=" + result);
        return result;
    }
}
