package com.bank.sched;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SchedulerDemo {

    private static final Logger log = Logger.getLogger(SchedulerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Batch Job Scheduler");
        // Job types: A=settlement, B=reconcile, C=report
        char[] jobs = {'A', 'A', 'A', 'B', 'B', 'C'};
        int cooldown = 2; // same job type must be 2 intervals apart

        BatchScheduler scheduler = new BatchScheduler();
        scheduler.leastIntervals(jobs, cooldown); // expect 8
    }
}
